import { describe, expect, it } from 'vitest';

import { computeLine } from '../src/invoice';

/**
 * Line computation golden rows — both pricing modes (D-58), taxonomy
 * short-circuits (D-60), zero-value retention (D-65), RCM passthrough
 * (D-54). Every expectation below is a hand-computed literal using the
 * RESEARCH Pattern 6 formulas — none were generated by running the
 * implementation.
 *
 * Odd-paisa split policy pinned here (RESEARCH Pitfall 5 mandate): the FULL
 * tax is computed first, halves use floor division, and ANY remainder paisa
 * is assigned deterministically to the CGST member.
 */

const INTRA = { head: 'CGST_SGST' } as const;
const INTER = { head: 'IGST' } as const;

function exclusive(overrides: Partial<Parameters<typeof computeLine>[0]> = {}) {
  return {
    qtyMilli: 1000n,
    unitPricePaise: 50000n,
    discountBps: 0n,
    pricingMode: 'exclusive',
    gstRateBps: 1800n,
    character: 'taxable',
    ...overrides,
  } as Parameters<typeof computeLine>[0];
}

describe('computeLine — exclusive mode per slab (taxable 50000p)', () => {
  it.each([
    ['nil 0%', 0n, 0n],
    ['0.25%', 25n, 125n],
    ['1.5%', 150n, 750n],
    ['3%', 300n, 1500n],
    ['5%', 500n, 2500n],
    ['18%', 1800n, 9000n],
    ['40%', 4000n, 20000n],
  ])('%s -> full tax %p', (_label, rateBps, tax) => {
    const result = computeLine(exclusive({ gstRateBps: rateBps }), INTRA);
    if (!result.ok) throw new Error(`unexpected rejection: ${result.reason}`);
    expect(result.taxablePaise).toBe(50000n);
    expect(result.taxPaise).toBe(tax);
  });

  it('intra splits an even tax exactly in half', () => {
    const result = computeLine(exclusive(), INTRA);
    if (!result.ok) throw new Error('unexpected rejection');
    expect(result.cgstPaise).toBe(4500n);
    expect(result.sgstOrUtgstPaise).toBe(4500n);
    expect(result.igstPaise).toBe(0n);
  });

  it('inter assigns the full tax to IGST with no halves', () => {
    const result = computeLine(exclusive(), INTER);
    if (!result.ok) throw new Error('unexpected rejection');
    expect(result.igstPaise).toBe(9000n);
    expect(result.cgstPaise).toBe(0n);
    expect(result.sgstOrUtgstPaise).toBe(0n);
    expect(result.taxPaise).toBe(9000n);
  });
});

describe('computeLine — odd-paisa split policy (CGST gets the remainder)', () => {
  it('tax 101p splits 51/50 (plan example)', () => {
    // 1 unit at Rs404.00 taxed at 0.25% => exactly 101 paise.
    const result = computeLine(
      exclusive({ unitPricePaise: 40400n, gstRateBps: 25n }),
      INTRA,
    );
    if (!result.ok) throw new Error('unexpected rejection');
    expect(result.taxPaise).toBe(101n);
    expect(result.cgstPaise).toBe(51n);
    expect(result.sgstOrUtgstPaise).toBe(50n);
    expect(result.cgstPaise + result.sgstOrUtgstPaise).toBe(result.taxPaise);
  });

  it('tax 185p splits 93/92 and inter keeps 185 whole', () => {
    // Rs123.45 at 1.5% => 185.175p -> half-up 185p (odd).
    const line = exclusive({ unitPricePaise: 12345n, gstRateBps: 150n });
    const intra = computeLine(line, INTRA);
    if (!intra.ok) throw new Error('unexpected rejection');
    expect(intra.taxPaise).toBe(185n);
    expect(intra.cgstPaise).toBe(93n);
    expect(intra.sgstOrUtgstPaise).toBe(92n);

    const inter = computeLine(line, INTER);
    if (!inter.ok) throw new Error('unexpected rejection');
    expect(inter.igstPaise).toBe(185n);
  });
});

describe('computeLine — discount applies before tax (exclusive)', () => {
  it('10% discount on a 3dp-quantity line', () => {
    // qty 2.500 @ Rs199.99 -> base 49998p (half-up from 49997.5);
    // 10% discount -> 4999.8p -> half-up 5000p; taxable 44998p;
    // 18% tax -> 8099.64p -> half-up 8100p -> 4050/4050.
    const result = computeLine(
      exclusive({
        qtyMilli: 2500n,
        unitPricePaise: 19999n,
        discountBps: 1000n,
      }),
      INTRA,
    );
    if (!result.ok) throw new Error('unexpected rejection');
    expect(result.taxablePaise).toBe(44998n);
    expect(result.taxPaise).toBe(8100n);
    expect(result.cgstPaise).toBe(4050n);
    expect(result.sgstOrUtgstPaise).toBe(4050n);
  });
});

describe('computeLine — inclusive mode extracts via residual method (D-58)', () => {
  it("D-58's own vector: MRP Rs500 @ 18% -> taxable 42373 + tax 7627", () => {
    const result = computeLine(
      exclusive({ pricingMode: 'inclusive' }),
      INTRA,
    );
    if (!result.ok) throw new Error('unexpected rejection');
    expect(result.taxablePaise).toBe(42373n);
    expect(result.taxPaise).toBe(7627n);
    expect(result.cgstPaise).toBe(3814n); // 7627 odd -> CGST gets remainder
    expect(result.sgstOrUtgstPaise).toBe(3813n);
    expect(result.taxablePaise + result.taxPaise).toBe(50000n);
  });

  it.each([
    ['nil 0%', 0n, 50000n, 0n],
    ['0.25%', 25n, 49875n, 125n],
    ['1.5%', 150n, 49261n, 739n],
    ['3%', 300n, 48544n, 1456n],
    ['5%', 500n, 47619n, 2381n],
    ['18%', 1800n, 42373n, 7627n],
    ['40%', 4000n, 35714n, 14286n],
  ])('%s inclusive of gross 50000p -> taxable %p + tax %p', (_label, rateBps, taxable, tax) => {
    const result = computeLine(exclusive({ pricingMode: 'inclusive', gstRateBps: rateBps }), INTRA);
    if (!result.ok) throw new Error(`unexpected rejection: ${result.reason}`);
    expect(result.taxablePaise).toBe(taxable);
    expect(result.taxPaise).toBe(tax);
    // Residual reconciliation holds for EVERY slab.
    expect(result.taxablePaise + result.taxPaise).toBe(50000n);
  });
});

describe('computeLine — non-slab rates gate only taxable characters', () => {
  it('taxable line with a non-slab rate rejects with the rates module reason', () => {
    const result = computeLine(exclusive({ gstRateBps: 1200n }), INTRA);
    expect(result).toEqual({ ok: false, reason: 'NOT_A_CURRENT_SLAB' });
  });

  it.each([
    ['exempt'],
    ['nil_rated'],
    ['non_gst'],
    ['zero_rated_taxable'],
  ] as const)('%s line short-circuits to zero tax even with junk rate field', (character) => {
    const result = computeLine(
      exclusive({ character, gstRateBps: 9999n }),
      INTRA,
    );
    if (!result.ok) throw new Error(`unexpected rejection for ${character}`);
    expect(result.taxPaise).toBe(0n);
    expect(result.cgstPaise).toBe(0n);
    expect(result.sgstOrUtgstPaise).toBe(0n);
    expect(result.igstPaise).toBe(0n);
  });
});

describe('computeLine — zero-value lines retained (D-65)', () => {
  it('qty 0 produces a present line with all-zero amounts', () => {
    const result = computeLine(exclusive({ qtyMilli: 0n }), INTRA);
    if (!result.ok) throw new Error('unexpected rejection');
    expect(result.taxablePaise).toBe(0n);
    expect(result.taxPaise).toBe(0n);
    expect(result.character).toBe('taxable'); // still a real line object
  });

  it('100% discount zeroes the line but keeps it in results', () => {
    const result = computeLine(exclusive({ discountBps: 10000n }), INTRA);
    if (!result.ok) throw new Error('unexpected rejection');
    expect(result.taxablePaise).toBe(0n);
    expect(result.taxPaise).toBe(0n);
  });
});

describe('computeLine — RCM flag rides through unchanged (D-54)', () => {
  it('rcm true echoes back and alters no arithmetic', () => {
    const plain = computeLine(exclusive(), INTRA);
    const rcm = computeLine(exclusive({ rcm: true }), INTRA);
    if (!plain.ok || !rcm.ok) throw new Error('unexpected rejection');
    expect(rcm.rcm).toBe(true);
    expect(plain.rcm).toBe(false);
    expect(rcm.taxablePaise).toBe(plain.taxablePaise);
    expect(rcm.taxPaise).toBe(plain.taxPaise);
    expect(rcm.cgstPaise).toBe(plain.cgstPaise);
  });
});

describe('computeLine — echoed inputs come back verbatim', () => {
  it('qty/price/discount/rate/mode/head echo', () => {
    const input = exclusive({ qtyMilli: 2500n, unitPricePaise: 19999n, discountBps: 1000n });
    const result = computeLine(input, { head: 'CGST_UTGST' });
    if (!result.ok) throw new Error('unexpected rejection');
    expect(result.qtyMilli).toBe(2500n);
    expect(result.unitPricePaise).toBe(19999n);
    expect(result.discountBps).toBe(1000n);
    expect(result.pricingMode).toBe('exclusive');
    expect(result.gstRateBps).toBe(1800n);
    expect(result.character).toBe('taxable');
    expect(result.head).toBe('CGST_UTGST');
  });
});
